def exponential(base, cap, attempts):
    return [min(cap, base * 2 ** n) for n in range(attempts)]

def full_jitter(base, cap, attempts, rng):
    return [rng.uniform(0, ceiling) for ceiling in exponential(base, cap, attempts)]

exercises.starter:
class CircuitOpen(Exception):
    pass

class Breaker:
    def __init__(self, threshold, cooldown):
        self.threshold = threshold
        self.cooldown = cooldown
        self.state = "closed"

    def call(self, now, fn):
        return fn()

exercises.tests:
calls = []
def ok():
    calls.append("ok"); return "fine"
def bad():
    calls.append("bad"); raise TimeoutError("slow")

b = Breaker(threshold=3, cooldown=10)
assert b.call(0, ok) == "fine"
for t in (1, 2):
    try: b.call(t, bad)
    except TimeoutError: pass
assert b.state == "closed"
assert b.call(3, ok) == "fine", "success resets the count"
for t in (4, 5, 6):
    try: b.call(t, bad)
    except TimeoutError: pass
assert b.state == "open"
n = len(calls)
try:
    b.call(10, ok); assert False, "should fail fast"
except CircuitOpen:
    pass
assert len(calls) == n, "an open breaker must not call fn"
try: b.call(16, bad)
except TimeoutError: pass
assert b.state == "open", "a failed trial reopens the breaker"
try:
    b.call(20, ok); assert False
except CircuitOpen:
    pass
assert b.call(26, ok) == "fine"
assert b.state == "closed"
try: b.call(27, bad)
except TimeoutError: pass
assert b.state == "closed", "the count started again from zero"

exercises.reference:
class CircuitOpen(Exception):
    pass

class Breaker:
    def __init__(self, threshold, cooldown):
        self.threshold = threshold
        self.cooldown = cooldown
        self.state = "closed"
        self.failures = 0
        self.opened_at = None

    def call(self, now, fn):
        if self.state == "open":
            if now - self.opened_at < self.cooldown:
                raise CircuitOpen()
            self.state = "half-open"
        try:
            result = fn()
        except Exception:
            self.failures += 1
            if self.state == "half-open" or self.failures >= self.threshold:
                self.state = "open"
                self.opened_at = now
            raise
        self.state = "closed"
        self.failures = 0
        return result

exercises.solution:
```python
class Breaker:
    def __init__(self, threshold, cooldown):
        self.threshold, self.cooldown = threshold, cooldown
        self.state, self.failures, self.opened_at = "closed", 0, None

    def call(self, now, fn):
        if self.state == "open":
            if now - self.opened_at < self.cooldown:
                raise CircuitOpen()              # fail fast, no call
            self.state = "half-open"             # one trial
        try:
            result = fn()
        except Exception:
            self.failures += 1
            if self.state == "half-open" or self.failures >= self.threshold:
                self.state, self.opened_at = "open", now
            raise
        self.state, self.failures = "closed", 0
        return result
```

The breaker is a small state machine. Two details matter in practice. A failed trial reopens the breaker for a *full* cooldown, so a still-broken dependency sees one request per cooldown rather than a stream. And in a real multi-threaded service, the half-open state must admit only one trial at a time — otherwise every waiting request rushes through together the moment the cooldown ends.
